config.script:
ids = self.view.custom.calendar.selection.ids
events = self.view.custom.schedule.data

#If only one event is selected for deletion and it is not recurring, we'll show the 'Are you sure'
#If multiple events are selected and thye are all recurring, we won't show the 'Are you sure' as the recurring change popup will appear

eventTypes = list(set([events[id]['rruleStr'] for id in ids]))	
if len(ids) == 1 and events[ids[0]]['rruleStr']: 
	shiftAssetPath = events[ids[0]]['assetPath']
	currentAssetPath = self.view.custom.assetInfo.assetPath
	if shiftAssetPath != currentAssetPath:
		system.perspective.openPopup("confirmDeletePopId",'kanoa/core/templates/inputs/confirm', params={'text':'Selected shift is inherited. Deleting this shift will it delete it from the original asset %s'%shiftAssetPath, 'messageHandler': 'deleteEvent'}, title='Delete Scheduled Event', modal=True, overlayDismiss=True, resizable=False)
	else:
		self.view.getChild("root").deleteEvents(None)
elif len(eventTypes) == 1 and eventTypes[0] is not None: self.view.getChild("root").deleteEvents(None)
else:
	system.perspective.openPopup("confirmDeletePopId",'kanoa/core/templates/inputs/confirm', params={'text':'Confirm to delete', 'messageHandler': 'deleteEvent'}, title='Delete Scheduled Event', modal=True, overlayDismiss=True, resizable=False)

return

